 "decisions": [
  {
   "title": "Data migrates to the target Oracle database",
   "context": "The target keeps its data in Oracle, while the legacy reads and writes tables in three Sybase databases (db_pagos, db_admin, db_cuentas) and calls db_cuentas..sp_debito.",
   "decision": "data_strategy is migration: the four tables (pg_orden, ad_tarifa_empresa, ad_servicio, ct_cuenta) move to the target database under snake_case names (payment_order, company_tariff, service_tariff, account) with the same column semantics and precision. The legacy qualified names are kept only as legacy_table for traceability.",
   "consequences": "The service no longer depends on the Sybase databases at runtime. A data migration and reconciliation of the four tables is required before cut-over, and every other consumer of those tables must be moved or fed from the new database."
  },
  {
   "title": "The debit is a port implemented in the target",
   "context": "sp_debito lives in Sybase and cannot be called once the data is in Oracle. It owns the account movements and returns the movement sequence as @o_secuencial.",
   "decision": "DebitGateway is kept as the port that replaces sp_debito (legacy_program db_cuentas..sp_debito). Its adapter is implemented in the target against the migrated account data, in the same database and the same transaction as the order update, and returns the movement sequence. The business logic of sp_debito (balance update, movement record) must be specified and approved as part of the migration.",
   "consequences": "The debit, the commission and the order update commit or roll back together. The behaviour of sp_debito is reimplemented, so it must be verified with the golden master and is a point of attention for the reviewer."
  },
  {
   "title": "One transaction from the first debit to the order update",
   "context": "The legacy opens the transaction (line 108) just before the debit and commits at line 161. It has three rollback points and no savepoints.",
   "decision": "PayOrder declares a unit of work with begin 108, commit 161 and three full rollbacks (119 -> DEBIT_FAILED, 136 -> COMMISSION_DEBIT_FAILED, 155 -> ORDER_UPDATE_FAILED). The validations before line 108 run without a transaction. Any rejection raises the business error, which undoes the transaction.",
   "consequences": "A debit is never kept when the commission debit or the order update fails. No UnitOfWork port is needed because there are no savepoints."
  },
  {
   "title": "Failure of the debit becomes an exception",
   "context": "The legacy checks @w_return <> 0 or @@error <> 0 after each debit. Error-code plumbing is not translated.",
   "decision": "The DebitGateway adapter raises a failure when the debit is not applied. The use case maps the first debit failure to DEBIT_FAILED and the commission failure to COMMISSION_DEBIT_FAILED. The movement sequence is the @o_secuencial output of the first debit only.",
   "consequences": "The commission debit has no returned movement, as in the legacy."
  },
  {
   "title": "Behaviour preserved on missing data",
   "context": "The legacy does not reject a missing account or service, because comparisons with NULL are not true and a NULL tariff becomes 0.",
   "decision": "If the account does not exist, the funds check does not reject and the debit is delegated to DebitGateway. If neither tariff exists, the tariff is 0. The canal input defaults to 'WEB' when absent, as in the legacy.",
   "consequences": "Same results as the legacy, and the behaviour is visible to reviewers."
  },
  {
   "title": "Decimal arithmetic",
   "context": "Amounts are money in the legacy (decimal(19,4)). The WEB commission is round(tarifa / 2, 2).",
   "decision": "Use BigDecimal with scale 4 (NUMBER(19,4) in Oracle) and round the half-tariff to 2 decimals with HALF_UP. The overdraft margin of 100.00 for non-VIR accounts is a business constant.",
   "consequences": "Results match the legacy for the golden master cases."
  },
  {
   "title": "Infrastructure not translated",
   "context": "The ERROR label calls cobis..sp_cerror to log the error and returns the error code.",
   "decision": "sp_cerror is not translated. Business exceptions carry a stable code and message, and the error handler of the framework replaces it.",
   "consequences": "The rejection message is returned through the message output and the error code of the response."
  }
