package com.bank.payments.adapters.out.jdbc;

import com.bank.payments.domain.model.ServiceTariff;
import com.bank.payments.domain.port.ServiceTariffRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.util.Optional;

/** JDBC adapter of the port ServiceTariffRepository (table service_tariff). */
@Repository
public class JdbcServiceTariffRepository implements ServiceTariffRepository {

    private final JdbcTemplate jdbcTemplate;

    public JdbcServiceTariffRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    @Override
    public Optional<ServiceTariff> findByCode(String servicio) {
        return jdbcTemplate.query(
                "SELECT srv_codigo, srv_tarifa FROM service_tariff WHERE srv_codigo = ? FETCH FIRST 1 ROWS ONLY",
                rs -> {
                    if (rs.next()) {
                        return Optional.of(new ServiceTariff(
                                rs.getString("srv_codigo"),
                                rs.getBigDecimal("srv_tarifa")));
                    }
                    return Optional.<ServiceTariff>empty();
                },
